import CharacterCards from '../flow/CharacterCards.jsx';

// Presentational: renders character sheets generated by DeepSeek for the illustrator chat
export default function CharacterSheetsStage({
  loading = false,
  characters = null,
  flow,
  isOpen = true,
  canSend = true,
  onApprove,
  onRequestChanges,
}) {
  if (loading) {
    return (
      <p className="video-detail__stage-hint">
        Cargando… DeepSeek está creando los personajes.
      </p>
    );
  }

  if (!characters || characters.length === 0) {
    return null;
  }

  return (
    <CharacterCards
      characters={characters}
      flow={flow}
      isOpen={isOpen}
      canSend={canSend}
      onApprove={onApprove}
      onRequestChanges={onRequestChanges}
    />
  );
}
